BEGIN;
DO $test$
DECLARE h uuid;pa uuid;pb uuid;child uuid;outsider uuid;b uuid:=gen_random_uuid();t uuid:=gen_random_uuid();r jsonb;n int;p jsonb:='{"name":"Rollback fictional venture","project":"Launch outline","stage":"Planning","release_date":null,"description":"Role verification only","is_archived":false}';q jsonb:='{"title":"Rollback fictional project task","project":"Launch outline","department":"Strategy","due_date":null}';
BEGIN
 SELECT household_id INTO STRICT h FROM bb_planner_private.routines WHERE routine_key='prepare_for_tomorrow_v1';
 SELECT user_id INTO STRICT pa FROM public.bb_planner_members WHERE household_id=h AND member_role='adult' ORDER BY user_id LIMIT 1;
 SELECT user_id INTO STRICT pb FROM public.bb_planner_members WHERE household_id=h AND member_role='adult' AND user_id<>pa LIMIT 1;
 SELECT user_id INTO STRICT child FROM public.bb_planner_members WHERE household_id=h AND member_role='child' LIMIT 1;
 SELECT user_id INTO STRICT outsider FROM public.bb_planner_members m WHERE NOT EXISTS(SELECT FROM public.bb_planner_members x WHERE x.household_id=h AND x.user_id=m.user_id) LIMIT 1;
 PERFORM set_config('request.jwt.claim.sub',pa::text,true);EXECUTE 'SET LOCAL ROLE authenticated';
 r:=public.bb_business_venture_save(h,b,NULL,p);IF r->>'created_by'<>pa::text OR (r->>'version')::int<>1 THEN RAISE EXCEPTION 'Creator';END IF;
 PERFORM public.bb_business_venture_save(h,b,NULL,p);
 r:=public.bb_business_task_write(h,b,t,NULL,'add',q);IF r->>'venture_id'<>b::text THEN RAISE EXCEPTION 'Venture binding';END IF;
 PERFORM public.bb_business_task_write(h,b,t,NULL,'add',q);
 BEGIN PERFORM public.bb_business_venture_save(h,gen_random_uuid(),NULL,p||'{"created_by":"spoof"}');RAISE EXCEPTION 'Unknown fields accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM public.bb_business_task_write(h,b,gen_random_uuid(),NULL,'add',q||'{"title":" "}');RAISE EXCEPTION 'Blank accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 PERFORM set_config('request.jwt.claim.sub',pb::text,true);
 SELECT count(*) INTO n FROM public.bb_business_ventures WHERE id=b;IF n<>1 THEN RAISE EXCEPTION 'Parent peer visibility';END IF;
 r:=public.bb_business_venture_save(h,b,1,p||'{"stage":"Building"}');IF (r->>'version')::int<>2 THEN RAISE EXCEPTION 'Peer venture edit';END IF;
 r:=public.bb_business_task_write(h,b,t,1,'complete','{"completed":true}');IF r->>'completed_by'<>pb::text OR r->>'completed_at' IS NULL THEN RAISE EXCEPTION 'Completion attribution';END IF;
 BEGIN PERFORM public.bb_business_task_write(h,b,t,1,'edit',q);RAISE EXCEPTION 'Stale accepted';EXCEPTION WHEN serialization_failure THEN NULL;END;
 BEGIN PERFORM public.bb_business_task_write(h,b,t,2,'complete','{"completed":null}');RAISE EXCEPTION 'Null accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 r:=public.bb_business_task_write(h,b,t,2,'complete','{"completed":false}');IF (r->>'completed')::boolean OR r->>'completed_by' IS NOT NULL THEN RAISE EXCEPTION 'Undo';END IF;
 PERFORM public.bb_business_task_write(h,b,t,3,'edit',q||'{"department":"Operations"}');
 BEGIN PERFORM public.bb_business_task_write(h,gen_random_uuid(),t,4,'edit',q);RAISE EXCEPTION 'Wrong venture accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM public.bb_business_task_write(h,b,t,4,'archive','{}');
 BEGIN PERFORM public.bb_business_task_write(h,b,t,5,'complete','{"completed":true}');RAISE EXCEPTION 'Archived task mutable';EXCEPTION WHEN object_not_in_prerequisite_state THEN NULL;END;
 PERFORM public.bb_business_venture_save(h,b,2,p||'{"is_archived":true}');
 BEGIN PERFORM public.bb_business_task_write(h,b,gen_random_uuid(),NULL,'add',q);RAISE EXCEPTION 'Archived venture mutable';EXCEPTION WHEN object_not_in_prerequisite_state THEN NULL;END;
 BEGIN UPDATE public.bb_business_ventures SET name='Direct bypass' WHERE id=b;RAISE EXCEPTION 'Direct update';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN INSERT INTO public.bb_business_tasks(id,household_id,venture_id,created_by,title,project,department) VALUES(gen_random_uuid(),h,b,pb,'Bypass','Bypass','Strategy');RAISE EXCEPTION 'Direct insert';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM set_config('request.jwt.claim.sub',child::text,true);
 SELECT count(*) INTO n FROM public.bb_business_ventures WHERE household_id=h;IF n<>0 THEN RAISE EXCEPTION 'Child venture leak';END IF;
 SELECT count(*) INTO n FROM public.bb_business_tasks WHERE household_id=h;IF n<>0 THEN RAISE EXCEPTION 'Child task leak';END IF;
 BEGIN PERFORM public.bb_business_venture_save(h,gen_random_uuid(),NULL,p);RAISE EXCEPTION 'Child create';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.bb_business_task_write(h,b,t,5,'complete','{"completed":true}');RAISE EXCEPTION 'Child complete';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM set_config('request.jwt.claim.sub',outsider::text,true);
 SELECT count(*) INTO n FROM public.bb_business_ventures WHERE household_id=h;IF n<>0 THEN RAISE EXCEPTION 'Foreign leak';END IF;
 BEGIN PERFORM public.bb_business_venture_save(h,gen_random_uuid(),NULL,p);RAISE EXCEPTION 'Foreign create';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM set_config('request.jwt.claim.sub','',true);
 BEGIN PERFORM public.bb_business_venture_save(h,gen_random_uuid(),NULL,p);RAISE EXCEPTION 'No identity create';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 EXECUTE 'SET LOCAL ROLE postgres';
 SELECT count(*) INTO n FROM bb_planner_private.business_changes WHERE target_id IN(b,t);IF n<>8 THEN RAISE EXCEPTION 'Audit count %',n;END IF;
 IF has_function_privilege('anon','public.bb_business_venture_save(uuid,uuid,bigint,jsonb)','EXECUTE') OR has_table_privilege('anon','public.bb_business_ventures','SELECT') OR has_table_privilege('authenticated','public.bb_business_tasks','DELETE') OR has_table_privilege('authenticated','bb_planner_private.business_changes','SELECT') OR pg_has_role('authenticated','bb_business_writer','MEMBER') THEN RAISE EXCEPTION 'ACL exposure';END IF;
 RAISE NOTICE 'PASS parents-only read/write, peer updates, versions, retries, completion attribution/undo, archive, child/foreign/no-identity denials, ACLs and audit';
END $test$;
ROLLBACK;
